my %seen; my @files;
sub walk { my($d)=@_; opendir my $dh,$d or return; for my $e(readdir $dh){next if $e eq '.'||$e eq '..'||$e eq '.git'; my $p="$d/$e"; if(-d $p){walk($p)} elsif($p =~ /\.go$/){push @files,$p}} closedir $dh }
walk('.');
for my $f(@files){next if $f =~ m{^\./store/}; open my $fh,'<',$f or next; local $/; my $s=<$fh>; close $fh; next unless $s =~ /github\.com\/usememos\/memos\/store(?:["`]|\s)/; my ($dir)=$f =~ m{^(.*)/[^/]+$}; $dir||='.'; for my $t(@types){ if($s =~ /\bstore\.$t\b/){$seen{$t}{$dir}=1} } }
for my $t(@types){ my @d=sort keys %{$seen{$t}||{}}; print "$t ".scalar(@d)." ".join(', ',@d)."\n" }
PL

